    // Maximal runs of fixed letters: {ch, start, end}.
    vector<array<long long, 3>> blocks;
    for (long long i = 0; i < n;) {
        if (s[i] == '.') { i++; continue; }
        long long st = i; char ch = s[i];
        while (i < n && s[i] == ch) i++;
        blocks.push_back({ch, st, i});
    }
    auto tri = [](long long z) { return z * (z + 1) / 2; };
    if (blocks.empty()) { printf("%lld\n", tri(n)); return 0; }
    // Merge neighbouring runs of the same letter (fill the dots between them).
    vector<array<long long, 3>> runs;
    for (auto &b : blocks) {
        if (!runs.empty() && runs.back()[0] == b[0]) runs.back()[2] = b[2];
        else runs.push_back(b);
    }
    int m = runs.size();
    vector<long long> len(m), gap;
    for (int i = 0; i < m; i++) len[i] = runs[i][2] - runs[i][1];
    len[0] += runs[0][1];
    len[m - 1] += n - runs[m - 1][2];
    for (int i = 0; i + 1 < m; i++) gap.push_back(runs[i + 1][1] - runs[i][2]);
    if (m == 1) { printf("%lld\n", tri(len[0])); return 0; }
    const long long NEG = LLONG_MIN / 4;
    // state 1: the preceding gap went to this run; state 0: it went to the left neighbour.
    long long dp[2] = {0, NEG};
    for (int i = 0; i + 1 < m; i++) {
        long long d = gap[i], nxt[2] = {NEG, NEG};
        for (int p = 0; p < 2; p++) {
            if (dp[p] == NEG) continue;
            long long base = len[i] + (i > 0 && p == 1 ? gap[i - 1] : 0);
            nxt[0] = max(nxt[0], dp[p] + tri(base + d));
            nxt[1] = max(nxt[1], dp[p] + tri(base));
        }
        dp[0] = nxt[0]; dp[1] = nxt[1];
    }
    long long ans = NEG;
    for (int st = 0; st < 2; st++)
        if (dp[st] != NEG) ans = max(ans, dp[st] + tri(len[m - 1] + (st == 1 ? gap[m - 2] : 0)));
    printf("%lld\n", ans);
}

import java.io.*;
import java.util.*;

public class Main {
    static long tri(long z) { return z * (z + 1) / 2; }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null) s = "";
        int n = s.length();
        // Maximal runs of fixed letters: {ch, start, end}.
        List<long[]> runs = new ArrayList<>();
        for (int i = 0; i < n;) {
            if (s.charAt(i) == '.') { i++; continue; }
            int st = i; char ch = s.charAt(i);
            while (i < n && s.charAt(i) == ch) i++;
            // Merge neighbouring runs of the same letter (fill the dots between them).
            if (!runs.isEmpty() && runs.get(runs.size() - 1)[0] == ch) runs.get(runs.size() - 1)[2] = i;
            else runs.add(new long[]{ch, st, i});
        }
        if (runs.isEmpty()) { System.out.println(tri(n)); return; }
        int m = runs.size();
        long[] len = new long[m], gap = new long[Math.max(m - 1, 0)];
        for (int i = 0; i < m; i++) len[i] = runs.get(i)[2] - runs.get(i)[1];
        len[0] += runs.get(0)[1];
        len[m - 1] += n - runs.get(m - 1)[2];
        for (int i = 0; i + 1 < m; i++) gap[i] = runs.get(i + 1)[1] - runs.get(i)[2];
        if (m == 1) { System.out.println(tri(len[0])); return; }
        final long NEG = Long.MIN_VALUE / 4;
        // state 1: the preceding gap went to this run; state 0: it went to the left neighbour.
        long[] dp = {0, NEG};
        for (int i = 0; i + 1 < m; i++) {
            long d = gap[i];
            long[] nxt = {NEG, NEG};
            for (int p = 0; p < 2; p++) {
                if (dp[p] == NEG) continue;
                long base = len[i] + (i > 0 && p == 1 ? gap[i - 1] : 0);
                nxt[0] = Math.max(nxt[0], dp[p] + tri(base + d));
                nxt[1] = Math.max(nxt[1], dp[p] + tri(base));
            }
            dp = nxt;
        }
        long ans = NEG;
        for (int st = 0; st < 2; st++)
            if (dp[st] != NEG) ans = Math.max(ans, dp[st] + tri(len[m - 1] + (st == 1 ? gap[m - 2] : 0)));
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strings"
)

func tri(z int64) int64 { return z * (z + 1) / 2 }

func main() {
	in := bufio.NewReader(os.Stdin)
	s, _ := in.ReadString('\n')
	s = strings.TrimRight(s, "\r\n")
	n := int64(len(s))
	// Maximal runs of fixed letters: {ch, start, end}; neighbouring runs of the same letter merge.
	var runs [][3]int64
	for i := int64(0); i < n; {
		if s[i] == '.' {
			i++
			continue
		}
		st, ch := i, s[i]
		for i < n && s[i] == ch {
			i++
		}
		if len(runs) > 0 && runs[len(runs)-1][0] == int64(ch) {
			runs[len(runs)-1][2] = i
		} else {
			runs = append(runs, [3]int64{int64(ch), st, i})
		}
	}
	if len(runs) == 0 {
		fmt.Println(tri(n))
		return
	}
	m := len(runs)
	length := make([]int64, m)
	for i := range runs {
		length[i] = runs[i][2] - runs[i][1]
	}
	length[0] += runs[0][1]
	length[m-1] += n - runs[m-1][2]
	gap := make([]int64, 0, m)
	for i := 0; i+1 < m; i++ {
		gap = append(gap, runs[i+1][1]-runs[i][2])
	}
	if m == 1 {
		fmt.Println(tri(length[0]))
		return
	}
	const NEG = math.MinInt64 / 4
	// state 1: the preceding gap went to this run; state 0: it went to the left neighbour.
	dp := [2]int64{0, NEG}
	for i := 0; i+1 < m; i++ {
		d := gap[i]
		nxt := [2]int64{NEG, NEG}
		for p := 0; p < 2; p++ {
			if dp[p] == NEG {
				continue
			}
			base := length[i]
			if i > 0 && p == 1 {
				base += gap[i-1]
			}
			nxt[0] = max(nxt[0], dp[p]+tri(base+d))
			nxt[1] = max(nxt[1], dp[p]+tri(base))
		}
		dp = nxt
	}
	ans := int64(NEG)
	for st := 0; st < 2; st++ {
		if dp[st] == NEG {
			continue
		}
		extra := int64(0)
		if st == 1 {
			extra = gap[m-2]
		}
		ans = max(ans, dp[st]+tri(length[m-1]+extra))
	}
	fmt.Println(ans)
}
